const DEFAULT_SCORING = {
  role: { buyer: 30, champion: 25, user: 15 },
  seniority: { executive: 15, director: 10, manager: 5 },
  bucket: { open_deal: 20, net_new: 15, lost_deal: 15, customer: 10 },
  icp: { strong: 15, partial: 8, unknown: 5, weak: 0 },
  recency: { within_3_months: 10, within_6_months: 5 },
  confidence: { high: 1, medium: 0.85, low: 0.6 },
  thresholds: { hot: 70, warm: 45 },
};

function scoringConfig(cfg) {
  const custom = parseJson(cfg.scoring, {}) || {};
  const out = {};
  for (const [k, v] of Object.entries(DEFAULT_SCORING)) out[k] = { ...v, ...(custom[k] || {}) };
  return out;
}

// Personas are matched against the new title (or the old one if the new title is unknown).
// cfg.personas: [{ "name": "Analyst", "keywords": ["analyst"], "points": 25 }, ...]
function matchPersona(cfg, title) {
  const personas = parseJson(cfg.personas, []) || [];
  const t = ` ${lower(title).replace(/[^a-z0-9]+/g, ' ')} `;
  // "analyst" also matches "analysts", "market" matches "marketing", but "product" does not match "production".
  const hit = (w) => new RegExp(` ${w.replace(/ /g, ' ')}(s|er|ers|ing)? `).test(t);
  let best = null;
  for (const p of Array.isArray(personas) ? personas : []) {
    const words = (p.keywords || []).map((w) => lower(w).replace(/[^a-z0-9]+/g, ' ').trim()).filter(Boolean);
    if (words.some(hit)) {
      if (!best || Number(p.points) > Number(best.points)) best = p;
    }
  }
  return best ? { name: clean(best.name), points: Number(best.points) || 0 } : { name: '', points: 0 };
}

function seniorityOf(title) {
  const t = lower(title);
  if (/\b(chief|c[eotfmipr]o|vp|svp|evp|vice president|head of|president|founder|co-founder|partner)\b/.test(t)) return 'executive';
  if (/\bdirector\b/.test(t)) return 'director';
  if (/\b(manager|lead|principal|staff)\b/.test(t)) return 'manager';
  return '';
}

function scoreAndRoute(cfg, candidate, verdictInput, accounts, nowInput) {
  const now = nowInput ? new Date(nowInput) : new Date();
  const S = scoringConfig(cfg);
  const recheckDays = Number(cfg.recheck_after_days) || 30;

  let v = verdictInput;
  if (typeof v === 'string') v = parseJson(v, {});
  if (v && typeof v === 'object' && v.output && typeof v.output === 'object') v = v.output;
  v = v || {};

  let outcome = ['confirmed', 'verify', 'no_change'].includes(lower(v.outcome)) ? lower(v.outcome) : 'verify';
  const confidence = ['high', 'medium', 'low'].includes(lower(v.confidence)) ? lower(v.confidence) : 'low';
  const sideRole = v.side_role === true || lower(v.side_role) === 'true';
  const newCompany = clean(v.new_company);
  const newDomain = normDomain(v.new_company_domain);
  const newTitle = clean(v.new_title);
  const started = clean(v.started_new_role);
  const icp = ['strong', 'partial', 'weak', 'unknown'].includes(lower(v.icp_fit)) ? lower(v.icp_fit) : 'unknown';
  let evidence = clean(v.evidence);

  // Guard rails on top of the agent's judgment.
  const oldDomain = normDomain(candidate.last_company_domain);
  const sameCompany = (newDomain && oldDomain && newDomain === oldDomain) || (newCompany && lower(newCompany) === lower(candidate.last_company));
  if (outcome === 'confirmed' && (sideRole || sameCompany || !newCompany)) outcome = 'verify';
  // A signal the data can't confirm yet stays open as [verify] until the profile updates or an AE closes it.
  if (outcome === 'no_change' && ['signal', 'recheck', 'retry'].includes(candidate.trigger)) outcome = 'verify';
  if (candidate.signal_evidence && !evidence.includes(candidate.signal_evidence)) {
    evidence = [`- ${candidate.signal_evidence}`, evidence].filter(Boolean).join('\n');
  }

  // Which account bucket is the new company in, and who owns it?
  let bucket = '';
  let account = null;
  if (outcome === 'confirmed') {
    account = (accounts || []).find((a) => normDomain(a.domain) && normDomain(a.domain) === newDomain) || null;
    const rel = account ? lower(account.relationship) : '';
    bucket = ['customer', 'open_deal', 'lost_deal'].includes(rel) ? rel : 'net_new';
  }

  // Score.
  const persona = outcome === 'confirmed' ? matchPersona(cfg, newTitle || candidate.last_title) : { name: '', points: 0 };
  let score = 0;
  const breakdown = {};
  if (outcome === 'confirmed') {
    breakdown.role = S.role[candidate.role_type] ?? S.role.user ?? 0;
    breakdown.persona = persona.points;
    breakdown.seniority = S.seniority[seniorityOf(newTitle)] ?? 0;
    breakdown.bucket = S.bucket[bucket] ?? 0;
    breakdown.icp = S.icp[icp] ?? 0;
    breakdown.recency = 0;
    const startDate = started ? new Date(started.length === 7 ? `${started}-01` : started) : null;
    if (startDate && !isNaN(startDate.getTime())) {
      const months = (now - startDate) / (30.4 * 86400000);
      if (months <= 3) breakdown.recency = S.recency.within_3_months ?? 0;
      else if (months <= 6) breakdown.recency = S.recency.within_6_months ?? 0;
    }
    const raw = Object.values(breakdown).reduce((a, b) => a + (Number(b) || 0), 0);
    breakdown.confidence_multiplier = S.confidence[confidence] ?? 1;
    score = Math.max(0, Math.min(100, Math.round(raw * breakdown.confidence_multiplier)));
  }
  const priority = outcome !== 'confirmed' ? '' : score >= S.thresholds.hot ? 'Hot' : score >= S.thresholds.warm ? 'Warm' : 'Cool';

  // Routing: the new account's owner if we already have one, otherwise the champion's own AE (cc'd when different).
  const champOwner = {
    name: candidate.owner_ae, email: candidate.owner_ae_email, slack_id: candidate.owner_ae_slack_id,
    crm_id: candidate.owner_crm_id, sequence_user_id: candidate.owner_sequence_user_id,
  };
  const acctOwner = account && clean(account.owner_ae || account.owner_ae_email || account.owner_crm_id)
    ? resolveOwner(loadDirectory(cfg), { name: account.owner_ae, email: account.owner_ae_email, slack_id: account.owner_ae_slack_id, crm_id: account.owner_crm_id, sequence_user_id: account.owner_sequence_user_id }, false)
    : null;
  const owner = acctOwner || champOwner;
  const sameOwner = acctOwner && ((acctOwner.email && acctOwner.email === lower(champOwner.email)) || lower(acctOwner.name) === lower(champOwner.name));
  const cc = acctOwner && !sameOwner && (champOwner.name || champOwner.email) ? champOwner : null;

  let status = 'active';
  let nextCheckOn = '';
  if (outcome === 'confirmed') status = 'moved';
  if (outcome === 'verify') { status = 'verify'; nextCheckOn = isoDay(new Date(now.getTime() + recheckDays * 86400000)); }

  return {
    candidate,
    outcome, confidence, side_role: sideRole, icp_fit: icp, evidence,
    new_company: outcome === 'confirmed' ? newCompany : '',
    new_company_domain: outcome === 'confirmed' ? newDomain : '',
    new_title: outcome === 'confirmed' ? newTitle : '',
    started_new_role: outcome === 'confirmed' ? started : '',
    draft_opener: outcome === 'confirmed' ? clean(v.draft_opener) : '',
    bucket,
    crm_account_id: account ? clean(account.crm_account_id) : '',
    persona: persona.name,
    score: outcome === 'confirmed' ? score : '',
    score_breakdown: breakdown,
    priority,
    owner,
    cc,
    status,
    next_check_on: nextCheckOn,
    // Alerts: every confirmed move, and [verify] only the first time (rechecks stay quiet).
    notify: outcome === 'confirmed' || (outcome === 'verify' && candidate.trigger !== 'recheck'),
    decided_at: now.toISOString(),
  };
}

// ---- n8n entry ----
const cfg = $('Config').first().json;
const accounts = $('Get Accounts').all().map((i) => i.json).filter((j) => j && j.domain);
const briefs = $('Prepare Brief').all();
const out = [];
$input.all().forEach((item, i) => {
  const idx = item.pairedItem && typeof item.pairedItem.item === 'number' ? item.pairedItem.item : i;
  const candidate = { ...briefs[idx].json };
  delete candidate.lookup_json;
  if (item.json.error) {
    // The agent failed for this person. Signal-based rows stay "suspect" and are retried in 2 days.
    console.log('Investigator error for', candidate.contact_id, item.json.error);
    return;
  }
  out.push({ json: scoreAndRoute(cfg, candidate, item.json.output, accounts) });
});
return out;

// Small helpers shared by the core logic. Inlined into each Code node by scripts/build-workflows.js.

const clean = (v) => String(v ?? '').trim();
const lower = (v) => clean(v).toLowerCase();
const truthy = (v) => ['true', 'yes', '1', 'y'].includes(lower(v));

function parseJson(value, fallback) {
  if (value && typeof value === 'object') return value;
  const s = clean(value);
  if (!s) return fallback;
  try { return JSON.parse(s); } catch (e) { return fallback; }
}

function normDomain(s) {
  let d = lower(s);
  if (!d) return '';
  d = d.replace(/^[a-z]+:\/\//, '').replace(/^www\./, '').split('/')[0].split('?')[0];
  if (d.includes('@')) d = d.split('@').pop();
  return d;
}

function splitName(full) {
  const parts = clean(full).split(/\s+/).filter(Boolean);
  if (!parts.length) return { first_name: '', last_name: '' };
  if (parts.length === 1) return { first_name: parts[0], last_name: '' };
  return { first_name: parts[0], last_name: parts.slice(1).join(' ') };
}

// Stable 1, 2 or 3 from a contact_id, so a third of the list is swept each month without anyone assigning groups.
function sweepGroupFor(id) {
  let h = 0;
  const s = clean(id);
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return String((h % 3) + 1);
}

const isoDay = (d) => d.toISOString().slice(0, 10);

// Team directory (Config): { "<email, CRM owner id or name>": { name, email, slack_id, crm_id, salesloft_user_id }, "default": {...} }
function loadDirectory(cfg) {
  const raw = parseJson(cfg.team_directory, {}) || {};
  const dir = {};
  for (const [k, v] of Object.entries(raw)) dir[lower(k)] = v && typeof v === 'object' ? v : {};
  return dir;
}

// Fills an owner's missing name / email / Slack ID / CRM ID / sequence user ID from the directory.
function resolveOwner(dir, owner, useDefault = true) {
  const o = owner || {};
  let entry = dir[lower(o.email)] || dir[lower(o.crm_id)] || dir[lower(o.name)];
  const hasOwner = clean(o.name) || clean(o.email) || clean(o.crm_id);
  if (!entry && !hasOwner && useDefault) entry = dir.default;
  entry = entry || {};
  return {
    name: clean(o.name) || clean(entry.name),
    email: lower(o.email) || lower(entry.email),
    slack_id: clean(o.slack_id) || clean(entry.slack_id),
    crm_id: clean(o.crm_id) || clean(entry.crm_id),
    sequence_user_id: clean(o.sequence_user_id) || clean(entry.salesloft_user_id || entry.sequence_user_id),
  };
}

// Builds the requests the core sends to optional connectors after a move is confirmed:
// find the new work email, write the move to the CRM, and enroll in a sequence.
// Pure functions: tested in test/, inlined into the matching Code nodes.


const NOOP = [{ action: 'noop' }];

function byContact(rows) {
  const m = new Map();
  for (const r of rows || []) if (r && clean(r.contact_id)) m.set(clean(r.contact_id), r);
  return m;
}

function personName(d) {
  const c = d.candidate;
  const split = splitName(c.full_name);
  return { first_name: clean(c.first_name) || split.first_name, last_name: clean(c.last_name) || split.last_name, full_name: clean(c.full_name) };
}

// Emails the lookup already found at the new company (Apollo returns these), so the email finder can skip them.
function lookupEmailResults(decisions) {
  return (decisions || [])
    .filter((d) => d.outcome === 'confirmed' && clean(d.candidate.lookup_email) && d.new_company_domain && clean(d.candidate.lookup_email).toLowerCase().endsWith(`@${d.new_company_domain}`))
    .map((d) => ({
      contact_id: d.candidate.contact_id,
      email: clean(d.candidate.lookup_email),
      status: lower(d.candidate.lookup_email_status) === 'verified' ? 'valid' : 'unknown',
      confidence: '',
      source: clean(d.candidate.lookup_source) || 'lookup',
    }));
}

function emailRequests(cfg, decisions) {
  const known = new Set(lookupEmailResults(decisions).map((r) => r.contact_id));
  const reqs = decisions
    .filter((d) => d.outcome === 'confirmed' && d.new_company_domain && !known.has(d.candidate.contact_id))
    .map((d) => ({ action: 'find_email', contact_id: d.candidate.contact_id, ...personName(d), domain: d.new_company_domain, company: d.new_company }));
  return reqs.length ? reqs : NOOP;
}

function crmRequests(cfg, decisions, emailResults) {
  if (!truthy(cfg.crm_write_back)) return NOOP;
  const emails = byContact(emailResults);
  const reqs = decisions
    .filter((d) => d.outcome === 'confirmed')
    .map((d) => {
      const c = d.candidate;
      const e = emails.get(c.contact_id) || {};
      const lines = [
        `Former ${c.role_type} at ${c.last_company || 'a previous company'} who used our product. Now ${d.new_title || 'at'} ${d.new_company}.`,
        d.priority ? `Priority: ${d.priority} (${d.score}/100)${d.persona ? `, persona: ${d.persona}` : ''}.` : '',
        d.evidence ? `Evidence:\n${d.evidence}` : '',
        c.notes ? `History with us: ${c.notes}` : '',
        d.draft_opener ? `Draft opener:\n${d.draft_opener}` : '',
      ].filter(Boolean);
      return {
        action: 'record_move',
        contact_id: c.contact_id,
        ...personName(d),
        new_email: clean(e.email),
        new_title: d.new_title,
        new_company: d.new_company,
        new_company_domain: d.new_company_domain,
        crm_account_id: d.crm_account_id,
        owner_crm_id: clean(d.owner.crm_id),
        old_company: c.last_company,
        old_crm_contact_id: c.source === 'product' ? '' : c.contact_id,
        task_subject: `Champion moved: ${c.full_name} is now at ${d.new_company}`,
        task_body: lines.join('\n\n'),
      };
    });
  return reqs.length ? reqs : NOOP;
}

function sequenceRequests(cfg, decisions, emailResults) {
  const minScore = Number(cfg.enroll_min_score ?? 45);
  const emails = byContact(emailResults);
  const reqs = [];
  for (const d of decisions) {
    if (d.outcome !== 'confirmed') continue;
    const e = emails.get(d.candidate.contact_id) || {};
    if (!clean(e.email) || lower(e.status) === 'invalid') continue;
    if ((Number(d.score) || 0) < minScore) continue;
    reqs.push({
      action: 'enroll',
      contact_id: d.candidate.contact_id,
      ...personName(d),
      email: clean(e.email),
      title: d.new_title,
      company: d.new_company,
      company_domain: d.new_company_domain,
      cadence_key: d.bucket,
      persona: d.persona,
      priority: d.priority,
      owner_email: clean(d.owner.email),
      owner_sequence_user_id: clean(d.owner.sequence_user_id),
      note: [d.draft_opener ? `Draft opener:\n${d.draft_opener}` : '', d.evidence ? `Why:\n${d.evidence}` : ''].filter(Boolean).join('\n\n'),
    });
  }
  return reqs.length ? reqs : NOOP;
}

// ---- n8n entry ----
return emailRequests($('Config').first().json, $('Score and Route').all().map((i) => i.json)).map((json) => ({ json }));

